export const runtimeHtml = `<!doctype html><html><head><meta charset="utf-8"><style>body{margin:24px;font-family:Arial}#u1{width:160px;height:48px;background:rgb(22,119,255);color:white;border:0;border-radius:6px}#overlay{position:fixed;pointer-events:none;border:2px solid #1677ff;display:none;z-index:100}</style></head><body><button id="u1">Contract element</button><div id="overlay"></div><script>
let inspecting=false;const button=document.querySelector('#u1');const overlay=document.querySelector('#overlay');
window.addEventListener('message',event=>{if(!['null',location.origin].includes(event.origin)||event.source!==parent)return;if(event.data.type==='AXURE_INSPECT_MODE'){inspecting=event.data.enabled;overlay.style.display='none'}});
button.addEventListener('mouseover',()=>{if(!inspecting)return;const box=button.getBoundingClientRect();Object.assign(overlay.style,{display:'block',left:box.x+'px',top:box.y+'px',width:box.width+'px',height:box.height+'px'})});
button.addEventListener('click',event=>{if(!inspecting)return;event.preventDefault();const box=button.getBoundingClientRect();parent.postMessage({type:'AXURE_INSPECT_ELEMENT',payload:{tagName:'BUTTON',id:'u1',className:'ax_default',text:button.textContent,position:{x:box.x,y:box.y,pageX:box.x,pageY:box.y},size:{width:box.width,height:box.height},typography:{fontFamily:'Arial',fontSize:'14px',fontWeight:'400',lineHeight:'normal',letterSpacing:'normal',textAlign:'center',color:'rgb(255, 255, 255)'},appearance:{backgroundColor:'rgb(22, 119, 255)',border:'0px none',borderRadius:'6px',opacity:'1'},spacing:{paddingTop:'4px',paddingRight:'8px',paddingBottom:'4px',paddingLeft:'8px'},html:button.outerHTML,assets:[{type:'svg',content:'<svg xmlns="http://www.w3.org/2000/svg"><rect width="10" height="10"/></svg>'},{type:'image',url:'/api/prototype-hub/public/mock-image.svg'}]}},'*')});
window.addEventListener('keydown',event=>{if(event.key==='Escape'){overlay.style.display='none';parent.postMessage({type:'AXURE_INSPECT_CLEAR'},'*')}});
</script></body></html>`

// Served over real HTTP: intercepted documents lose Chrome address-space metadata for sandbox scripts.
export const anchorRuntimeHtml = `<!doctype html><html><head><style>body{display:flow-root;margin:0;width:1600px;height:2200px;font-family:Arial}iframe{position:absolute;left:100px;top:200px;width:300px;height:160px}button,a{display:block;margin:16px}</style></head><body><button id="root-action">Browse action</button><a href="child.html" id="navigate">Internal navigation</a><iframe title="Nested frame" src="nested.html"></iframe><script data-prototype-hub-inspector src="/api/prototype-hub/public/inspector.js"></script></body></html>`
